// Parse Telegram message
const item = $input.first().json;

const parsedMessage = {
  platform: 'telegram',
  user_id: item.message.from.id.toString(),
  username: item.message.from.username || item.message.from.first_name,
  chat_id: item.message.chat.id.toString(),
  message_id: item.message.message_id.toString(),
  text: item.message.text || '',
  timestamp: new Date(item.message.date * 1000).toISOString(),
  is_bot_command: (item.message.text || '').startsWith('/'),
  raw_message: item
};

// Extract command if present
if (parsedMessage.is_bot_command) {
  const parts = parsedMessage.text.split(' ');
  parsedMessage.command = parts[0].substring(1);
  parsedMessage.args = parts.slice(1);
}

return { json: parsedMessage };

// Parse Slack message
const item = $input.first().json;
const event = item.event || {};

const parsedMessage = {
  platform: 'slack',
  user_id: event.user || '',
  username: event.username || 'user',
  chat_id: event.channel || '',
  message_id: event.ts || '',
  text: event.text || '',
  timestamp: new Date(parseFloat(event.ts || 0) * 1000).toISOString(),
  is_bot_command: (event.text || '').startsWith('/'),
  channel_type: event.channel_type || 'unknown',
  raw_message: item
};

// Extract command if present
if (parsedMessage.is_bot_command) {
  const parts = parsedMessage.text.split(' ');
  parsedMessage.command = parts[0].substring(1);
  parsedMessage.args = parts.slice(1);
}

return { json: parsedMessage };

// Handle bot commands
const message = $input.first().json;

const commandHandlers = {
  'start': {
    response: '👋 Welcome! I\'m your AI assistant. Here are available commands:\n\n/help - Show this message\n/status - Check system status\n/weather <city> - Get weather information\n/news <topic> - Get latest news\n/reminder <text> - Set a reminder',
    action: 'send_message'
  },
  'help': {
    response: '📚 *Available Commands*\n\n• /start - Get started\n• /status - System status\n• /weather <city> - Weather info\n• /news <topic> - Latest news\n• /reminder <text> - Set reminder\n• /analyze <text> - Text analysis\n\nJust send me any message for AI conversation!',
    action: 'send_message'
  },
  'status': {
    response: '✅ *System Status*\n\n🟢 All systems operational\n🤖 AI Engine: Online\n📊 Response Time: < 1s\n💾 Database: Connected\n\nLast Updated: ' + new Date().toLocaleString(),
    action: 'send_message'
  },
  'weather': {
    response: 'Fetching weather data...',
    action: 'fetch_weather',
    requires_args: true
  },
  'news': {
    response: 'Fetching latest news...',
    action: 'fetch_news',
    requires_args: false
  },
  'reminder': {
    response: 'Setting your reminder...',
    action: 'create_reminder',
    requires_args: true
  },
  'analyze': {
    response: 'Analyzing your text...',
    action: 'analyze_text',
    requires_args: true
  }
};

const handler = commandHandlers[message.command];

if (!handler) {
  return {
    json: {
      ...message,
      response: '❌ Unknown command. Type /help for available commands.',
      action: 'send_message'
    }
  };
}

if (handler.requires_args && (!message.args || message.args.length === 0)) {
  return {
    json: {
      ...message,
      response: `⚠️ This command requires arguments. Usage: /${message.command} <parameters>`,
      action: 'send_message'
    }
  };
}

return {
  json: {
    ...message,
    response: handler.response,
    action: handler.action
  }
};

// Format AI response
const message = $input.first().json;
const aiResponse = message.choices?.[0]?.message?.content || 'Sorry, I couldn\'t process that.';

return {
  json: {
    ...message,
    response: aiResponse,
    action: 'send_message',
    ai_processed: true
  }
};

// Format weather response
const data = $input.first().json;

if (data.cod === 200) {
  const weather = data.weather[0];
  const main = data.main;

  const response = `🌤 *Weather in ${data.name}, ${data.sys.country}*\n\n` +
    `🌡 Temperature: ${main.temp}°C (feels like ${main.feels_like}°C)\n` +
    `📊 Conditions: ${weather.main} - ${weather.description}\n` +
    `💧 Humidity: ${main.humidity}%\n` +
    `💨 Wind Speed: ${data.wind.speed} m/s\n` +
    `🔽 Pressure: ${main.pressure} hPa\n\n` +
    `_Updated: ${new Date().toLocaleString()}_`;

  return {
    json: {
      ...data,
      response: response,
      action: 'send_message'
    }
  };
} else {
  return {
    json: {
      ...data,
      response: '❌ Could not fetch weather data. Please check the city name and try again.',
      action: 'send_message'
    }
  };
}
